   372  bool
   373  hb_buffer_t::move_to (unsigned int i)
   374  {
   375    if (!have_output)
   376    {
   377      assert (i <= len);
   378      idx = i;
   379      return true;
   380    }
   381    if (unlikely (!successful))
   382      return false;
   383
   384    assert (i <= out_len + (len - idx));
   385
   386    if (out_len < i)
   387    {
   388      unsigned int count = i - out_len;
   389      if (unlikely (!make_room_for (count, count))) return false;
   390
   391      memmove (out_info + out_len, info + idx, count * sizeof (out_info[0]));
   392      idx += count;
   393      out_len += count;
   394    }
   395    else if (out_len > i)
   396    {
   397      /* Tricky part: rewinding... */
   398      unsigned int count = out_len - i;
   399
   400      /* This will blow in our face if memory allocation fails later
   401       * in this same lookup... */
   402      if (unlikely (idx < count && !shift_forward (count + 32))) return false;
   403
   404      assert (idx >= count);
   405
   406      idx -= count;
   407      out_len -= count;
   408      memmove (info + idx, out_info + out_len, count * sizeof (out_info[0]));
   409    }
   410
   411    return true;
   412  }
